def transform(grid):
    h,w=len(grid),len(grid[0])
    from collections import Counter
    counts=Counter(v for row in grid for v in row)
    bg=counts.most_common(1)[0][0]
    marker=max((v for v in counts if v!=bg),key=lambda v:counts[v])
    # find longest contiguous horizontal or vertical run of non-background, non-marker cells
    best=None
    for r in range(h):
        c=0
        while c<w:
            if grid[r][c] not in (bg,marker):
                start=c
                while c<w and grid[r][c] not in (bg,marker): c+=1
                if c-start>1 and (best is None or c-start>len(best[2])):
                    best=(r,start,[grid[r][x] for x in range(start,c)],'h')
            else:c+=1
    for c in range(w):
        r=0
        while r<h:
            if grid[r][c] not in (bg,marker):
                start=r
                while r<h and grid[r][c] not in (bg,marker): r+=1
                if r-start>1 and (best is None or r-start>len(best[2])):
                    best=(start,c,[grid[x][c] for x in range(start,r)],'v')
            else:r+=1
    if best is None:return [row[:] for row in grid]
    r0,c0,seq,axis=best
    k=len(seq)//2
    out=[row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c]==marker:
                for i,v in enumerate(seq):
                    rr=r+i-k if axis=='v' else r
                    cc=c+i-k if axis=='h' else c
                    if 0<=rr<h and 0<=cc<w:out[rr][cc]=v
    return out
